static void mix_mono_at(StereoBuffer& dst, const Buffer& src,
                        double t_sec, float gain, int sr)
{
    const size_t off = (size_t)(t_sec * sr);
    for (size_t i = 0; i < src.size() && off + i < dst.size(); ++i) {
        dst.L[off + i] += src[i] * gain;
        dst.R[off + i] += src[i] * gain;
    }
}

static void mix_stereo_at(StereoBuffer& dst, const StereoBuffer& src,
                          double t_sec, float gain, int sr)
{
    const size_t off = (size_t)(t_sec * sr);
    for (size_t i = 0; i < src.size() && off + i < dst.size(); ++i) {
        dst.L[off + i] += src.L[i] * gain;
        dst.R[off + i] += src.R[i] * gain;
    }
}

// Oboe — alto sax 1/2
static Buffer make_oboe(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.60);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.22);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.08);
    double vib = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        vib += TWO_PI * 5.8 / sr;
        if (vib >= TWO_PI) vib -= TWO_PI;
        double t = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.10) / 0.10));
        double vd = std::sin(vib) * freq * (std::pow(2.0, 7.0/1200.0) - 1.0) * ve;
        o1.frequency = freq + vd;
        buf[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    }
    SVFilter lp(SVFilter::Mode::LowPass, 4000.0, 0.65);
    lp.process(buf, sr);
    double rel = std::min(0.08, d * 0.20);
    ADSR env(0.015, d * 0.08, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Clarinet — tenor sax 1/2
static Buffer make_clarinet(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.55);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.25);
    Oscillator o3(WaveShape::Sine, freq * 0.5, 0.12);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    SVFilter lp(SVFilter::Mode::LowPass, 3000.0, 0.65);
    lp.process(buf, sr);
    double atk = std::min(0.10, d * 0.20);
    double rel = std::min(0.20, d * 0.22);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.75, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Bassoon — bari sax
static Buffer make_bassoon(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Triangle, freq,       0.48);
    Oscillator o2(WaveShape::Sine,     freq * 2.0, 0.24);
    Oscillator o3(WaveShape::Sine,     freq * 0.5, 0.22);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    BiquadEQ body(BiquadEQ::Type::Peak,   500.0, 3.5, 2.0);
    SVFilter   lp(SVFilter::Mode::LowPass, 2200.0, 0.72);
    body.process(buf, sr);
    lp.process(buf, sr);
    double rel = std::min(0.10, d * 0.18);
    ADSR env(0.04, d * 0.12, 0.80, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Trumpet — trumpets 1-4
static Buffer make_trumpet(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.55);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.22);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.10);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    SVFilter tr_lp(SVFilter::Mode::LowPass, 2200.0, 0.62);
    tr_lp.process(buf, sr);
    double atk = std::min(0.06, d * 0.15);
    double rel = std::min(0.15, d * 0.20);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.68, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Trombone — trombones 1-3
static Buffer make_trombone(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.55);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.20);
    Oscillator o3(WaveShape::Sine, freq * 0.5, 0.18);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    SVFilter lp(SVFilter::Mode::LowPass, 1800.0, 0.62);
    lp.process(buf, sr);
    double atk = std::min(0.08, d * 0.18);
    double rel = std::min(0.20, d * 0.22);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.72, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Tuba / contrabass — bass trombone + bass guitar
static Buffer make_tuba(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine,     freq,       0.60);
    Oscillator o2(WaveShape::Sine,     freq * 2.0, 0.28);
    Oscillator o3(WaveShape::Triangle, freq,       0.10);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    SVFilter lp(SVFilter::Mode::LowPass,  800.0, 0.68);
    lp.process(buf, sr);
    double atk = std::min(0.06, d * 0.15);
    double rel = std::min(0.15, d * 0.20);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.85, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Contrabass — bass guitar low end
static Buffer make_contrabass(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Sine, freq,       0.65);
    Oscillator o2(WaveShape::Sine, freq * 2.0, 0.22);
    Oscillator o3(WaveShape::Sine, freq * 3.0, 0.08);
    for (auto& s : buf) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    SVFilter lp(SVFilter::Mode::LowPass, 500.0, 0.60);
    lp.process(buf, sr);
    double atk = std::min(0.12, d * 0.20);
    double rel = std::min(0.50, d * 0.28);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.86, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Harp / pizzicato — guitar
static StereoBuffer make_harp(double freq, double dur, int sr)
{
    double d = std::max(0.08, std::min(dur, 0.90));
    Buffer mono = make_buffer(d, sr);
    Oscillator o1(WaveShape::Triangle, freq,       0.58);
    Oscillator o2(WaveShape::Sine,     freq * 2.0, 0.26);
    Oscillator o3(WaveShape::Sine,     freq * 3.0, 0.10);
    for (auto& s : mono) s = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    std::vector<AutoPoint> cut = {{0.0,8500.0f},{0.010,4500.0f},{0.12,2000.0f},{d,600.0f}};
    mono = apply_filter_automation(mono, cut, 1.2, SVFilter::Mode::LowPass, sr);
    for (size_t i = 0; i < mono.size(); ++i) {
        double t = (double)i / sr;
        mono[i] *= (float)((t < 0.004) ? t / 0.004 : std::exp(-(t - 0.004) * 8.0));
    }
    return haas_widen(mono, 8.0, sr);
}

// Violin / flute — piano high
static StereoBuffer make_violin(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer mono = make_buffer(d, sr);
    Oscillator o1(WaveShape::Triangle, freq,         0.52);
    Oscillator o2(WaveShape::Sine,     freq * 2.0,   0.26);
    Oscillator o3(WaveShape::Sine,     freq * 3.0,   0.10);
    double vib_phase = 0.0;
    const double vib_depth = freq * (std::pow(2.0, 5.0/1200.0) - 1.0);
    for (size_t i = 0; i < mono.size(); ++i) {
        vib_phase += TWO_PI * 5.5 / sr;
        if (vib_phase >= TWO_PI) vib_phase -= TWO_PI;
        double t  = (double)i / sr;
        double ve = std::min(1.0, std::max(0.0, (t - 0.12) / 0.12));
        double vib = std::sin(vib_phase) * vib_depth * ve;
        o1.frequency = freq + vib;
        mono[i] = o1.tick(sr) + o2.tick(sr) + o3.tick(sr);
    }
    BiquadEQ form(BiquadEQ::Type::Peak, 2500.0, 1.2, 2.5);
    form.process(mono, sr);
    SVFilter lp(SVFilter::Mode::LowPass, 2800.0, 0.62);
    lp.process(mono, sr);
    double atk = std::min(0.06, d * 0.15);
    double rel = std::min(0.25, d * 0.22);
    DAHDSR env(0.0, atk, 0.0, d * 0.10, 0.68, rel);
    env.apply(mono, d, std::max(0.0, d - rel), sr);
    return haas_widen(mono, 12.0, sr);
}

// Cello section — piano low
static Buffer make_cello(double freq, double dur, int sr)
{
    double d = std::max(0.02, dur);
    Buffer buf = make_buffer(d, sr);
    Oscillator o1(WaveShape::Triangle, freq,       0.50);
    Oscillator o2(WaveShape::Sine,     freq * 2.0, 0.24);
    Oscillator o3(WaveShape::Sine,     freq * 0.5, 0.22);
    double fl = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        fl += TWO_PI * 6.0 / sr;
        if (fl >= TWO_PI) fl -= TWO_PI;
        buf[i] = (o1.tick(sr) + o2.tick(sr) + o3.tick(sr)) * (1.0f + 0.04f * (float)std::sin(fl));
    }
    BiquadEQ body(BiquadEQ::Type::Peak,   320.0, 1.2, 1.8);
    SVFilter   lp(SVFilter::Mode::LowPass, 2500.0, 0.62);
    body.process(buf, sr);
    lp.process(buf, sr);
    double atk = std::min(0.10, d * 0.18);
    double rel = std::min(0.38, d * 0.25);
    DAHDSR env(0.0, atk, 0.0, d * 0.12, 0.65, rel);
    env.apply(buf, d, std::max(0.0, d - rel), sr);
    return buf;
}

// Timpani
static Buffer make_timpani(double pitch_freq = 90.0)
{
    const double dur = 1.20;
    Buffer buf = make_buffer(dur, SR);
    NoiseGenerator ng(41u);
    double phase = 0.0;
    for (size_t i = 0; i < buf.size(); ++i) {
        double t = (double)i / SR;
        double f = pitch_freq * (1.0 + 0.12 * std::exp(-t * 12.0));
        phase += TWO_PI * f / SR;
        if (phase >= TWO_PI) phase -= TWO_PI;
        buf[i] = (float)(std::sin(phase) * std::exp(-t * 4.5))
               + ng.tick_white() * (float)std::exp(-t * 30.0) * 0.18f;
    }
    SVFilter lp(SVFilter::Mode::LowPass, 420.0, 0.8);
    lp.process(buf, SR);
    normalize(buf, 0.90f);
    return buf;
}

static Buffer make_orch_snare()
{
    const double dur = 0.22;
    NoiseGenerator ng(17u);
    Buffer buf = ng.render(dur, SR);
    SVFilter bp(SVFilter::Mode::BandPass, 2200.0, 2.2);
    bp.process(buf, SR);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 28.0);
    Buffer body = make_buffer(dur, SR);
    Oscillator ob(WaveShape::Sine, 220.0, 0.45);
    for (size_t i = 0; i < body.size(); ++i)
        body[i] = ob.tick(SR) * (float)std::exp(-(double)i / SR * 40.0);
    mix_into(buf, body, 0.55f);
    normalize(buf, 0.75f);
    return buf;
}

static Buffer make_crash()
{
    const double dur = 1.80;
    NoiseGenerator ng(199u);
    Buffer buf = ng.render(dur, SR);
    HighPassFilter hpf(5000.0, SR);
    hpf.process(buf);
    BiquadEQ shim(BiquadEQ::Type::Peak, 8000.0, 3.0, 3.0);
    shim.process(buf, SR);
    for (size_t i = 0; i < buf.size(); ++i)
        buf[i] *= (float)std::exp(-(double)i / SR * 2.8);
    normalize(buf, 0.42f);
    return buf;
}

static void print_help(const char* prog) {
    std::cout
        << "Shiawase VIP - Orchestral Arrangement\n"
        << "Usage:\n  " << prog << " [options]\n\n"
        << "  -o, --output <file>   Output WAV (default: shiawase_orch.wav)\n"
        << "      --play            Play after rendering\n"
        << "  -h, --help            Show help\n";
}

int main(int argc, char** argv)
{
    std::string output  = "shiawase_orch.wav";
    bool        do_play = false;

    for (int i = 1; i < argc; ++i) {
        std::string a = argv[i];
        if (a == "-o" || a == "--output") {
            if (i + 1 < argc) output = argv[++i];
            else { std::cerr << "Missing argument\n"; return 1; }
        } else if (a == "--play") {
            do_play = true;
        } else if (a == "-h" || a == "--help") {
            print_help(argv[0]); return 0;
        } else {
            std::cerr << "Unknown: " << a << "\n"; return 1;
        }
    }

    global_config().sample_rate = SR;
    global_config().channels    = 2;
    global_config().bits        = 16;

    constexpr double TOTAL_DUR = 184.0;
    const size_t total = (size_t)(TOTAL_DUR * SR);

    std::cout << "Shiawase VIP - Orchestral Arrangement\n"
              << "  150 BPM  |  " << std::fixed << std::setprecision(1)
              << TOTAL_DUR << " s\n\n";

    StereoBuffer master(total, 0.0f);

    const Buffer kick_buf  = make_timpani(73.4);
    const Buffer snare_buf = make_orch_snare();
    const Buffer crash_buf = make_crash();

    std::cout << "  [1/11] Timpani / percussion...\n" << std::flush;
    for (int i = 0; i < kick_times_count;  ++i) mix_mono_at(master, kick_buf,  kick_times[i],  0.38f, SR);
    for (int i = 0; i < snare_times_count; ++i) mix_mono_at(master, snare_buf, snare_times[i], 0.22f, SR);
    for (int i = 0; i < crash_times_count; ++i) mix_mono_at(master, crash_buf, crash_times[i], 0.16f, SR);

    std::cout << "  [2/11] Contrabass (bass guitar)...\n" << std::flush;
    for (int i = 0; i < bass_guitar_notes_count; ++i) {
        const NoteEvent& n = bass_guitar_notes[i];
        mix_mono_at(master, make_contrabass(n.freq, n.dur, SR), n.t, 0.28f, SR);
    }

    std::cout << "  [3/11] Tuba (bass trombone)...\n" << std::flush;
    for (int i = 0; i < bass_trombone_notes_count; ++i) {
        const NoteEvent& n = bass_trombone_notes[i];
        mix_mono_at(master, make_tuba(n.freq, n.dur, SR), n.t, 0.24f, SR);
    }

    std::cout << "  [4/11] Bassoon (bari sax)...\n" << std::flush;
    for (int i = 0; i < bari_sax_notes_count; ++i) {
        const NoteEvent& n = bari_sax_notes[i];
        mix_mono_at(master, make_bassoon(n.freq, n.dur, SR), n.t, 0.22f, SR);
    }

    std::cout << "  [5/11] Cello section (piano low)...\n" << std::flush;
    for (int i = 0; i < piano_lo_notes_count; ++i) {
        const NoteEvent& n = piano_lo_notes[i];
        mix_mono_at(master, make_cello(n.freq, n.dur, SR), n.t, 0.24f, SR);
    }

    std::cout << "  [6/11] Trombone section (trombones 1-3)...\n" << std::flush;
    for (int i = 0; i < trombone1_notes_count; ++i) {
        const NoteEvent& n = trombone1_notes[i];
        mix_mono_at(master, make_trombone(n.freq, n.dur, SR), n.t, 0.18f, SR);
    }
    for (int i = 0; i < trombone2_notes_count; ++i) {
        const NoteEvent& n = trombone2_notes[i];
        mix_mono_at(master, make_trombone(n.freq, n.dur, SR), n.t, 0.16f, SR);
    }
    for (int i = 0; i < trombone3_notes_count; ++i) {
        const NoteEvent& n = trombone3_notes[i];
        mix_mono_at(master, make_trombone(n.freq, n.dur, SR), n.t, 0.14f, SR);
    }

    std::cout << "  [7/11] Clarinet (tenor sax 1+2)...\n" << std::flush;
    for (int i = 0; i < tenor_sax1_notes_count; ++i) {
        const NoteEvent& n = tenor_sax1_notes[i];
        mix_mono_at(master, make_clarinet(n.freq, n.dur, SR), n.t, 0.18f, SR);
    }
    for (int i = 0; i < tenor_sax2_notes_count; ++i) {
        const NoteEvent& n = tenor_sax2_notes[i];
        mix_mono_at(master, make_clarinet(n.freq, n.dur, SR), n.t, 0.16f, SR);
    }

    std::cout << "  [8/11] Trumpet section (trumpets 1-4)...\n" << std::flush;
    for (int i = 0; i < trumpet1_notes_count; ++i) {
        const NoteEvent& n = trumpet1_notes[i];
        mix_mono_at(master, make_trumpet(n.freq, n.dur, SR), n.t, 0.20f, SR);
    }
    for (int i = 0; i < trumpet2_notes_count; ++i) {
        const NoteEvent& n = trumpet2_notes[i];
        mix_mono_at(master, make_trumpet(n.freq, n.dur, SR), n.t, 0.18f, SR);
    }
    for (int i = 0; i < trumpet3_notes_count; ++i) {
        const NoteEvent& n = trumpet3_notes[i];
        mix_mono_at(master, make_trumpet(n.freq, n.dur, SR), n.t, 0.16f, SR);
    }
    for (int i = 0; i < trumpet4_notes_count; ++i) {
        const NoteEvent& n = trumpet4_notes[i];
        mix_mono_at(master, make_trumpet(n.freq, n.dur, SR), n.t, 0.14f, SR);
    }

    std::cout << "  [9/11] Harp (guitar)...\n" << std::flush;
    for (int i = 0; i < guitar_notes_count; ++i) {
        const NoteEvent& n = guitar_notes[i];
        StereoBuffer sb = make_harp(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.20f, SR);
    }

    std::cout << "  [10/11] Violin / strings (piano high)...\n" << std::flush;
    for (int i = 0; i < piano_hi_notes_count; ++i) {
        const NoteEvent& n = piano_hi_notes[i];
        StereoBuffer sb = make_violin(n.freq, n.dur, SR);
        mix_stereo_at(master, sb, n.t, 0.24f, SR);
    }

    std::cout << "  [11/11] Oboe lead (alto sax 1+2)...\n" << std::flush;
    for (int i = 0; i < alto_sax1_notes_count; ++i) {
        const NoteEvent& n = alto_sax1_notes[i];
        mix_mono_at(master, make_oboe(n.freq, n.dur, SR), n.t, 0.26f, SR);
    }
    for (int i = 0; i < alto_sax2_notes_count; ++i) {
        const NoteEvent& n = alto_sax2_notes[i];
        mix_mono_at(master, make_oboe(n.freq, n.dur, SR), n.t, 0.22f, SR);
    }

    std::cout << "\n  Master bus...\n" << std::flush;

    Reverb rvL; rvL.room_size = 0.80f; rvL.wet = 0.22f; rvL.dry = 0.90f; rvL.init(SR);
    Reverb rvR; rvR.room_size = 0.82f; rvR.wet = 0.22f; rvR.dry = 0.90f; rvR.init(SR);
    rvL.process(master.L);
    rvR.process(master.R);

    ParametricEQ eq;
    eq.low_shelf  = BiquadEQ(BiquadEQ::Type::LowShelf,  120.0, -2.0, 0.7);
    eq.peak       = BiquadEQ(BiquadEQ::Type::Peak,       600.0, -6.0, 1.5);
    eq.high_shelf = BiquadEQ(BiquadEQ::Type::HighShelf, 7000.0, -3.0, 0.7);
    eq.process(master, SR);

    distortion::apply_soft_clip(master.L, 2.50f);
    distortion::apply_soft_clip(master.R, 2.50f);

    fade_in(master,  0.25, SR);
    fade_out(master, 3.00, SR);

    normalize(master, 0.28f);
    clamp_buffer(master);

    std::cout << "  Writing: " << output << "\n";
    save_wav_stereo(master, output, SR);
    std::cout << "  Done.\n";

    if (do_play) {
        std::cout << "  Playing (press Enter to stop)...\n";
        PlaybackHandle h = play_async(master, SR);
        std::thread([h]() mutable { std::cin.get(); h.stop(); }).detach();
        h.wait();
    }

    return 0;
}
